import { FC, useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useIntl } from 'react-intl'
import axios from 'axios'
import { Modal, Button, Form } from 'react-bootstrap'
import { PageTitle } from '../../../../_metronic/layout/core'
import { KTIcon, exportToExcel, exportToCsv } from '../../../../_metronic/helpers'

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:8001/api';

interface OrderItem {
    item_id: number
    name: string
    sku: string
    price: number
    qty_ordered: number
    vendor?: string
    seller_name?: string
    seller_phone?: string
    seller_id?: string | number
    frais_livraison?: number
    product_image?: string | null
}

interface Order {
    entity_id: number
    increment_id: string
    status: string
    status_label?: string
    grand_total: number
    order_currency_code: string
    customer_firstname: string
    customer_lastname: string
    customer_email: string
    created_at: string
    billing_address?: {
        city: string
        street: string[]
        telephone: string
    }
    items: OrderItem[]
    payment?: {
        method?: string
    }
}

interface MagentoOrderResponse {
    items: Order[]
    total_count: number
    search_criteria: any
}

const MagentoOrdersAvailabilityPage: FC = () => {
    const [orders, setOrders] = useState<Order[]>([])
    const [loading, setLoading] = useState<boolean>(true)
    const [totalCount, setTotalCount] = useState<number>(0)
    const [currentPage, setCurrentPage] = useState<number>(1);
    const [itemsPerPage, setItemsPerPage] = useState<number>(50);
    const [searchTerm, setSearchTerm] = useState<string>('');
    const [startDate, setStartDate] = useState<string>('');
    const [endDate, setEndDate] = useState<string>('');
    const navigate = useNavigate()
    const intl = useIntl()

    const [showModal, setShowModal] = useState<boolean>(false)
    const [showExportModal, setShowExportModal] = useState<boolean>(false)
    const [isExporting, setIsExporting] = useState<boolean>(false)
    const [selectedOrder, setSelectedOrder] = useState<Order | null>(null)
    const [notifyCustomer, setNotifyCustomer] = useState<boolean>(false)
    const [isConfirmMode, setIsConfirmMode] = useState<boolean>(false)

    const [showDetailsAlert, setShowDetailsAlert] = useState(false);
    const [alertMessage, setAlertMessage] = useState('');
    const [alertType, setAlertType] = useState<'success' | 'error' | 'warning' | 'info'>('success');

    const fetchOrders = async (isBackground: boolean = false) => {
        try {
            if (!isBackground) setLoading(true)
            const params = new URLSearchParams();
            params.append('limit', itemsPerPage.toString());
            params.append('page', currentPage.toString());
            params.append('status', 'pending');

            if (searchTerm) params.append('search', searchTerm);
            if (startDate) params.append('start_date', startDate);
            if (endDate) params.append('end_date', endDate);
            params.append('sort_field', 'entity_id');
            params.append('sort_dir', 'DESC');
            params.append('fresh', 'true');

            const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8001/api';
            const response = await axios.get<MagentoOrderResponse>(`${apiUrl}/magento/orders?${params.toString()}`)

            if (response.data && response.data.items) {
                const validItems = response.data.items.filter(item => item && typeof item === 'object');
                setOrders(validItems)
                setTotalCount(response.data.total_count)
            } else {
                setOrders([]);
                setTotalCount(0);
            }

            if (!isBackground) setLoading(false)
        } catch (err) {
            console.error(err)
            if (!isBackground) setLoading(false)
        }
    }

    useEffect(() => {
        fetchOrders()
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [currentPage, searchTerm, itemsPerPage, startDate, endDate])

    const updateStatus = (orderId: number, newStatus: string) => {
        axios.post(`${API_URL}/magento/orders/${orderId}/status`, {
            status: newStatus,
            notify_customer: notifyCustomer
        })
            .then(() => {
                setAlertMessage(`Order #${orderId} set to <strong>${getStatusLabel(newStatus)}</strong>${notifyCustomer ? ' (Customer Notified)' : ''}`);
                setAlertType('success');
                setShowDetailsAlert(true);
                setTimeout(() => setShowDetailsAlert(false), 3000);
                
                // Clear notification state after success
                setNotifyCustomer(false);
                
                fetchOrders();
            })
            .catch(error => {
                setAlertMessage(`Failed to update status: ${error.message}`);
                setAlertType('error');
                setShowDetailsAlert(true);
                setTimeout(() => setShowDetailsAlert(false), 4000);
            });
    };

    const STATUS_LABELS: Record<string, string> = {
        'Produits_dispo': intl.formatMessage({id: 'STATUS.PRODUITS_DISPO'}),
        'Produits_nondispo': intl.formatMessage({id: 'STATUS.PRODUITS_NONDISPO'}),
        'produits disponibles': intl.formatMessage({id: 'STATUS.PRODUITS_DISPO'}),
        'produits non disponibles': intl.formatMessage({id: 'STATUS.PRODUITS_NONDISPO'}),
        'pending': intl.formatMessage({id: 'STATUS.PENDING'}),
        'canceled': intl.formatMessage({id: 'STATUS.CANCELED'}),
        'complete': intl.formatMessage({id: 'STATUS.COMPLETE'}),
        'holded': intl.formatMessage({id: 'STATUS.ON_HOLD'}),
        'confirmée': intl.formatMessage({id: 'STATUS.CONFIRMED'}),
        'confirmee': intl.formatMessage({id: 'STATUS.CONFIRMED'}),
        'processing': intl.formatMessage({id: 'STATUS.PROCESSING'}),
        'livraison en cours': 'Livraison en cours',
        'livraison_encours': 'Livraison en cours',
        'partiellement livrée': 'Partiellement livrée',
        'livrée': intl.formatMessage({id: 'STATUS.DELIVERED'}),
        'closed': intl.formatMessage({id: 'STATUS.CLOSED'}),
        'fraud': intl.formatMessage({id: 'STATUS.FRAUD'}),
        'pending_payment': 'En attente de paiement'
    };

    const getStatusLabel = (status: string, statusLabel?: string): string => {
        if (status && STATUS_LABELS[status]) return STATUS_LABELS[status];
        if (status && STATUS_LABELS[status.toLowerCase()]) return STATUS_LABELS[status.toLowerCase()];
        if (statusLabel) return statusLabel;
        return status ? status.charAt(0).toUpperCase() + status.slice(1) : '';
    };

    const getStatusColor = (status: string) => {
        const s = status ? status.toLowerCase() : '';
        if (s.includes('dispo') && !s.includes('non')) return 'success';
        if (s.includes('non dispo')) return 'danger';
        if (['processing', 'pending', 'en cours'].some(k => s.includes(k))) return 'primary';
        return 'light';
    };

    const handleShowOrder = (order: Order) => {
        setSelectedOrder(order)
        setShowModal(true)
        setIsConfirmMode(false)
    }

    const handleOpenConfirmModal = (order: Order) => {
        setSelectedOrder(order)
        setShowModal(true)
        setIsConfirmMode(true)
    }

    const handleConfirmOrder = (skipBordereau: boolean = false) => {
        if (selectedOrder) {
            updateStatus(selectedOrder.entity_id, 'confirmée')
            setShowModal(false)
            setSelectedOrder(null)
            setIsConfirmMode(false)
        }
    }

    const handleCloseModal = () => {
        setShowModal(false)
        setSelectedOrder(null)
        setIsConfirmMode(false)
    }

    const fetchAllOrdersForExport = async (): Promise<Order[]> => {
        try {
            setIsExporting(true);
            const params = new URLSearchParams();
            params.append('limit', '999999');
            params.append('page', '1');
            params.append('status', 'pending');
            if (searchTerm) params.append('search', searchTerm);
            if (startDate) params.append('start_date', startDate);
            if (endDate) params.append('end_date', endDate);
            params.append('sort_field', 'entity_id');
            params.append('sort_dir', 'DESC');
            params.append('fresh', 'false');

            const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8001/api';
            const response = await axios.get<MagentoOrderResponse>(`${apiUrl}/magento/orders?${params.toString()}`);

            if (response.data && response.data.items) {
                return response.data.items.filter(item => item && typeof item === 'object');
            }
            return [];
        } catch (err) {
            console.error('Failed to fetch orders for export:', err);
            return [];
        } finally {
            setIsExporting(false);
        }
    };

    const getExportData = (ordersList: Order[]) => {
        return ordersList.flatMap(order => {
            if (!order.items || order.items.length === 0) {
                return [{
                    "Numéro commande": `\u200C${order.increment_id}`,
                    "Nom Client": `${order.customer_firstname} ${order.customer_lastname}`,
                    "Statut": getStatusLabel(order.status, order.status_label),
                    "Date": order.created_at ? new Date(order.created_at).toLocaleDateString() : 'N/A',
                    "Heure": order.created_at ? new Date(order.created_at).toLocaleTimeString() : 'N/A',
                    "SKU": "N/A",
                    "Produit": "N/A",
                    "QTY": 0,
                    "Prix Unitaire": 0,
                    "Frais": 0,
                    "Vendeur": 'Arkan',
                    "Total Commande": `${order.grand_total} ${order.order_currency_code}`,
                    "Ville": order.billing_address?.city || 'N/A',
                    "Téléphone": order.billing_address?.telephone || 'N/A'
                }];
            }

            return order.items.map(item => {
                const sellerName = item.seller_name || item.vendor || 'Arkan';
                
                return {
                    "Numéro commande": `\u200C${order.increment_id}`,
                    "Nom Client": `${order.customer_firstname} ${order.customer_lastname}`,
                    "Statut": getStatusLabel(order.status, order.status_label),
                    "Date": order.created_at ? new Date(order.created_at).toLocaleDateString() : 'N/A',
                    "Heure": order.created_at ? new Date(order.created_at).toLocaleTimeString() : 'N/A',
                    "SKU": `\u200C${item.sku}`,
                    "Produit": item.name,
                    "QTY": item.qty_ordered,
                    "Prix Unitaire": item.price,
                    "Frais": item.frais_livraison || 0,
                    "Vendeur": sellerName,
                    "Total Commande": `${order.grand_total} ${order.order_currency_code}`,
                    "Ville": order.billing_address?.city || 'N/A',
                    "Téléphone": order.billing_address?.telephone || 'N/A'
                };
            });
        });
    };

    const handleExportCsv = async () => {
        const allOrders = await fetchAllOrdersForExport();
        const dataToExport = getExportData(allOrders);
        exportToCsv(dataToExport, 'availability_export');
        setShowExportModal(false);
    };

    const handleExportXls = async () => {
        const allOrders = await fetchAllOrdersForExport();
        const dataToExport = getExportData(allOrders);
        exportToExcel(dataToExport, 'availability_export', 'Orders');
        setShowExportModal(false);
    };


    const totalPages = Math.ceil(totalCount / itemsPerPage);

    const [sellerPhones, setSellerPhones] = useState<{ [key: string]: string }>({});
    const [tempPhones, setTempPhones] = useState<{ [key: string]: string }>({});

    const [showCommentModal, setShowCommentModal] = useState<boolean>(false)
    const [selectedItemForComment, setSelectedItemForComment] = useState<OrderItem | null>(null)
    const [itemComment, setItemComment] = useState<string>('')
    const [commenting, setCommenting] = useState<boolean>(false)
    const [savingPhone, setSavingPhone] = useState<{ [key: string]: boolean }>({});
    const [editingPhone, setEditingPhone] = useState<{ [key: string]: boolean }>({});
    const [sendingWhatsApp] = useState<{ [key: number]: boolean }>({});

    const handlePhoneChange = (sellerId: string, phone: string) => {
        setTempPhones(prev => ({ ...prev, [sellerId]: phone }));
    };

    const savePhone = async (item: OrderItem) => {
        const sellerKey = item.seller_name || item.vendor || 'Unknown';
        const phone = tempPhones[sellerKey];
        if (!phone || !phone.trim()) return;

        // Optimistically update local state so WhatsApp button appears immediately
        setSellerPhones(prev => ({ ...prev, [sellerKey]: phone.trim() }));

        // If we have a seller_id, persist to the backend
        if (item.seller_id && item.seller_id !== 'arkan') {
            setSavingPhone(prev => ({ ...prev, [sellerKey]: true }));
            try {
                await axios.put(`${API_URL}/vendeurs/${item.seller_id}/phone`, {
                    phone: phone.trim()
                });
                setAlertMessage(`Numéro de téléphone mis à jour pour <strong>${sellerKey}</strong>`);
                setAlertType('success');
                setShowDetailsAlert(true);
                setTimeout(() => setShowDetailsAlert(false), 3000);
            } catch (error: any) {
                setAlertMessage(`Échec de la mise à jour du téléphone: ${error.response?.data?.message || error.message}`);
                setAlertType('error');
                setShowDetailsAlert(true);
                setTimeout(() => setShowDetailsAlert(false), 5000);
            } finally {
                setSavingPhone(prev => ({ ...prev, [sellerKey]: false }));
            }
        } else {
            // No seller_id — just keep the local state (session-only)
            setAlertMessage(`Numéro sauvegardé localement pour <strong>${sellerKey}</strong> (aucun ID vendeur trouvé)`);
            setAlertType('info');
            setShowDetailsAlert(true);
            setTimeout(() => setShowDetailsAlert(false), 3000);
        }
    };

    /**
     * Opens a WhatsApp link with a pre-filled message for the vendor.
     */
    const sendWhatsAppMessage = (phone: string, item: OrderItem, orderId: number) => {
        const cleanPhone = phone.replace(/[^\d]/g, '');
        // Format for international (Tunisia 216) if it's 8 digits
        const finalPhone = cleanPhone.length === 8 ? `216${cleanPhone}` : cleanPhone;
        
        const message = `Bonjour,\n\n` +
                        `Merci de confirmer la disponibilité de l'article suivant :\n\n` +
                        `Produit : ${item.name}\n` +
                        `SKU : ${item.sku}\n` +
                        `Commande : #${orderId}\n\n` +
                        `Est-il disponible en stock ? Merci d'avance.\n` +
                        `Cordialement, l'équipe Arkan.`;
        
        const encodedMessage = encodeURIComponent(message);
        const whatsappUrl = `https://wa.me/${finalPhone}?text=${encodedMessage}`;
        
        window.open(whatsappUrl, '_blank');
        
        setAlertMessage(`Ouverture de WhatsApp pour ${item.name}`);
        setAlertType('info');
        setShowDetailsAlert(true);
        setTimeout(() => setShowDetailsAlert(false), 3000);
    };

    const handleOpenCommentModal = (item: OrderItem) => {
        setSelectedItemForComment(item)
        setItemComment('')
        setShowCommentModal(true)
    }

    const handleCloseCommentModal = () => {
        setShowCommentModal(false)
        setSelectedItemForComment(null)
        setItemComment('')
    }

    const submitComment = async () => {
        if (!selectedOrder || !selectedItemForComment || !itemComment.trim()) return

        setCommenting(true)
        try {
            const fullComment = `${selectedItemForComment.name}: ${itemComment}`
            await axios.post(`${API_URL}/magento/orders/${selectedOrder.entity_id}/comments`, {
                comment: fullComment
            })
            setAlertType('success')
            setAlertMessage(`Comment added successfully for ${selectedItemForComment.name}`)
            setShowDetailsAlert(true)
            setTimeout(() => setShowDetailsAlert(false), 3000)
            handleCloseCommentModal()
        } catch (err: any) {
            console.error('Error adding comment:', err)
            setAlertType('error')
            setAlertMessage(`Failed to add comment: ${err.response?.data?.message || err.message}`)
            setShowDetailsAlert(true)
            setTimeout(() => setShowDetailsAlert(false), 5000)
        } finally {
            setCommenting(false)
        }
    }

    return (
        <>
            {showDetailsAlert && (
                <div className={`notice d-flex bg-light-${alertType} rounded border-${alertType} border border-dashed p-6 mb-5`}
                    style={{ position: 'fixed', top: '20px', left: '50%', transform: 'translateX(-50%)', zIndex: 9999, minWidth: '400px' }}>
                    <KTIcon iconName="information-5" className={`fs-2tx text-${alertType} me-4`} />
                    <div className="d-flex flex-column">
                        <h4 className="text-gray-900 fw-bold">{alertType.toUpperCase()}</h4>
                        <div className="fs-6 text-gray-700" dangerouslySetInnerHTML={{ __html: alertMessage }}></div>
                    </div>
                </div>
            )}
            <PageTitle breadcrumbs={[]}>{intl.formatMessage({id: 'ORDERS.PAGE_TITLE_AVAILABILITY'})}</PageTitle>

            <div className='card mb-5 mb-xl-8'>
                <div className='card-header border-0 pt-5'>
                    <h3 className='card-title align-items-start flex-column'>
                        <span className='card-label fw-bold fs-3 mb-1'>{intl.formatMessage({id: 'ORDERS.CHECK_AVAILABILITY'})}</span>
                        <span className='text-muted mt-1 fw-semibold fs-7'>{intl.formatMessage({id: 'ORDERS.TOTAL_PENDING'}, {count: totalCount})}</span>
                    </h3>
                    <div className='card-toolbar'>
                        <div className='d-flex align-items-center position-relative my-1 me-3'>
                            <span className='fs-7 fw-bold text-gray-700 me-2'>{intl.formatMessage({id: 'ORDERS.HEADER_DATE'})} (Debut):</span>
                            <input
                                type='date'
                                className='form-control form-control-solid w-150px'
                                value={startDate}
                                onChange={(e) => { setStartDate(e.target.value); setCurrentPage(1); }}
                            />
                        </div>
                        <div className='d-flex align-items-center position-relative my-1 me-3'>
                            <span className='fs-7 fw-bold text-gray-700 me-2'>{intl.formatMessage({id: 'ORDERS.HEADER_DATE'})} (Fin):</span>
                            <input
                                type='date'
                                className='form-control form-control-solid w-150px'
                                value={endDate}
                                onChange={(e) => { setEndDate(e.target.value); setCurrentPage(1); }}
                            />
                        </div>
                        <div className='d-flex align-items-center position-relative my-1 me-3'>
                            <button 
                                className='btn btn-light-success' 
                                onClick={() => setShowExportModal(true)}
                                disabled={orders.length === 0}
                            >
                                <KTIcon iconName='exit-up' className='fs-2' />
                                {intl.formatMessage({id: 'ECOMMERCE.COMMON.FILTER'})} Export
                            </button>
                        </div>
                        <div className='d-flex align-items-center position-relative my-1'>
                            <KTIcon iconName='magnifier' className='fs-1 position-absolute ms-6' />
                            <input
                                type='text'
                                className='form-control form-control-solid w-250px ps-14'
                                placeholder={intl.formatMessage({id: 'ORDERS.SEARCH_PLACEHOLDER'})}
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                            />
                        </div>
                    </div>
                </div>
                <div className='card-body py-3'>
                    <div className='table-responsive'>
                        <table className='table table-row-bordered table-row-gray-100 align-middle gs-0 gy-3'>
                            <thead>
                                <tr className='fw-bold text-muted'>
                                    <th className='ps-4 min-w-100px'>{intl.formatMessage({id: 'ORDERS.HEADER_ORDER'})}</th>
                                    <th className='min-w-200px'>{intl.formatMessage({id: 'ORDERS.HEADER_PRODUCTS'})}</th>
                                    <th className='min-w-120px'>{intl.formatMessage({id: 'ORDERS.HEADER_SELLER'})}</th>
                                    <th className='min-w-100px'>{intl.formatMessage({id: 'ORDERS.HEADER_STATUS'})}</th>
                                    <th className='min-w-100px'>{intl.formatMessage({id: 'ORDERS.HEADER_TOTAL'})}</th>
                                    <th className='min-w-100px'>{intl.formatMessage({id: 'ORDERS.HEADER_DATE'})}</th>
                                    <th className='min-w-200px text-end rounded-end pe-4'>{intl.formatMessage({id: 'ORDERS.HEADER_VERIFICATION'})}</th>
                                </tr>
                            </thead>
                            <tbody>
                                {loading ? (
                                    <tr><td colSpan={10} className="text-center">{intl.formatMessage({id: 'ORDERS.LOADING'})}</td></tr>
                                ) : (
                                    orders.map((order) => {
                                        const sellers = Array.from(new Set(order.items?.map(i => i.seller_name || i.vendor).filter(v => !!v)));
                                        const productNames = order.items?.map(i => i.name).join(', ') || 'No items';

                                        return (
                                            <tr key={order.entity_id} onClick={() => handleShowOrder(order)} style={{ cursor: 'pointer' }}>
                                                <td className='ps-4 fw-bold text-hover-primary fs-6'>
                                                    {order.increment_id}
                                                </td>
                                                <td>
                                                    <div className="text-gray-800 fw-semibold fs-7" style={{ maxWidth: '250px', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }} title={productNames}>
                                                        {productNames}
                                                    </div>
                                                </td>
                                                  <td>
                                                    {sellers.length > 1 ? (
                                                        <span className="badge badge-light-warning">{intl.formatMessage({id: 'ORDERS.LABEL_MULTIPLE'})}</span>
                                                    ) : (
                                                        <span className="text-danger fw-bold">{sellers[0] || intl.formatMessage({id: 'ORDERS.LABEL_UNKNOWN'})}</span>
                                                    )}
                                                </td>
                                                <td>
                                                    <span className={`badge badge-light-${getStatusColor(order.status_label || order.status)} fw-bold`}>
                                                        {getStatusLabel(order.status, order.status_label)}
                                                    </span>
                                                </td>
                                                <td className='text-success fw-bold fs-6'>{order.grand_total} {order.order_currency_code}</td>
                                                <td className='text-muted fw-semibold fs-6'>{new Date(order.created_at).toLocaleDateString()}</td>
                                                <td className='text-end' onClick={(e) => e.stopPropagation()}>
                                                    <button
                                                        className='btn btn-light-primary btn-sm me-2'
                                                        onClick={() => handleOpenConfirmModal(order)}
                                                        title={intl.formatMessage({id: 'ORDERS.ACTION_CONFIRM'})}
                                                    >
                                                        <KTIcon iconName="check-circle" className="fs-3" /> {intl.formatMessage({id: 'ORDERS.ACTION_CONFIRM'})}
                                                    </button>
                                                    <button
                                                        className='btn btn-light-success btn-sm me-2'
                                                        onClick={() => updateStatus(order.entity_id, 'Produits_dispo')}
                                                    >
                                                        <KTIcon iconName="check" className="fs-3" /> {intl.formatMessage({id: 'ORDERS.ACTION_AVAILABLE'})}
                                                    </button>
                                                    <button
                                                        className='btn btn-light-danger btn-sm'
                                                        onClick={() => updateStatus(order.entity_id, 'Produits_nondispo')}
                                                    >
                                                        <KTIcon iconName="cross" className="fs-3" /> {intl.formatMessage({id: 'ORDERS.ACTION_NOT_AVAILABLE'})}
                                                    </button>
                                                </td>
                                            </tr>
                                        );
                                    })
                                )}
                            </tbody>
                        </table>
                    </div>

                    {!loading && totalCount > 0 && (
                        <div className="d-flex justify-content-between align-items-center mt-4">
                            <div className='d-flex align-items-center'>
                                <span className='text-gray-600 me-2'>{intl.formatMessage({id: 'ORDERS.PAGINATION_ROWS'})}:</span>
                                <select
                                    className='form-select form-select-sm form-select-solid w-75px'
                                    value={itemsPerPage}
                                    onChange={(e) => {
                                        setItemsPerPage(Number(e.target.value))
                                        setCurrentPage(1)
                                    }}
                                >
                                    <option value={10}>10</option>
                                    <option value={20}>20</option>
                                    <option value={50}>50</option>
                                    <option value={100}>100</option>
                                </select>
                            </div>
                            <span className="text-gray-600">{intl.formatMessage({id: 'ORDERS.PAGINATION_PAGE_OF'}, {page: currentPage, total: totalPages})}</span>
                            <div className="d-flex gap-2">
                                <button className="btn btn-sm btn-light-primary" onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))} disabled={currentPage === 1}>{intl.formatMessage({id: 'ORDERS.PAGINATION_PREVIOUS'})}</button>
                                <button className="btn btn-sm btn-light-primary" onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))} disabled={currentPage === totalPages}>{intl.formatMessage({id: 'ORDERS.PAGINATION_NEXT'})}</button>
                            </div>
                        </div>
                    )}
                </div>
            </div>

            {selectedOrder && (
                <Modal show={showModal} onHide={handleCloseModal} size="xl" dialogClassName="modal-xl mw-1200px">
                    <Modal.Header closeButton>
                        <Modal.Title>{intl.formatMessage({id: 'MODAL.DETAILS_TITLE'})} #{selectedOrder.increment_id}</Modal.Title>
                    </Modal.Header>
                    <Modal.Body>
                        <div className="row mb-5">
                            <div className="col-md-4">
                                <h5 className="fw-bold text-gray-800">{intl.formatMessage({id: 'MODAL.CUSTOMER_INFO'})}</h5>
                                <p className="text-gray-600">
                                    <span className="fw-bold">{intl.formatMessage({id: 'AUTH.INPUT.FULLNAME'})}:</span> {selectedOrder.customer_firstname} {selectedOrder.customer_lastname}<br />
                                    <span className="fw-bold">{intl.formatMessage({id: 'AUTH.INPUT.EMAIL'})}:</span> {selectedOrder.customer_email}<br />
                                    <span className="fw-bold">{intl.formatMessage({id: 'ORDERS.HEADER_DATE'})}:</span> {new Date(selectedOrder.created_at).toLocaleString()}
                                </p>
                            </div>
                            <div className="col-md-4">
                                <h5 className="fw-bold text-gray-800">{intl.formatMessage({id: 'MODAL.BILLING_ADDRESS'})}</h5>
                                <p className="text-gray-600">
                                    {selectedOrder.billing_address?.street?.join(', ')}<br />
                                    {selectedOrder.billing_address?.city}<br />
                                    <span className="fw-bold">Tel:</span> {selectedOrder.billing_address?.telephone}
                                </p>
                            </div>
                            <div className="col-md-4">
                                <h5 className="fw-bold text-gray-800">{intl.formatMessage({id: 'MODAL.ORDER_TOTALS'})}</h5>
                                <p className="text-gray-600">
                                    <span className="fw-bold">{intl.formatMessage({id: 'MODAL.GRAND_TOTAL'})}:</span> {selectedOrder.grand_total} {selectedOrder.order_currency_code}<br />
                                    <span className="fw-bold">{intl.formatMessage({id: 'ORDERS.HEADER_STATUS'})}:</span>
                                    <span className={`badge badge-light-${getStatusColor(selectedOrder.status_label || selectedOrder.status)} fw-bold ms-2`}>
                                        {getStatusLabel(selectedOrder.status, selectedOrder.status_label)}
                                    </span><br />
                                    <span className="fw-bold">{intl.formatMessage({id: 'MODAL.PAYMENT_METHOD'})}:</span> {selectedOrder.payment?.method?.replace('payment', '').replace('_', ' ') || 'N/A'}
                                </p>
                            </div>
                        </div>

                        <h5 className="fw-bold text-gray-800 mb-3">{intl.formatMessage({id: 'MENU.PRODUCTS'})}</h5>
                        <div className="table-responsive">
                            <table className="table table-row-bordered table-row-gray-100 align-middle">
                                <thead>
                                    <tr className="fw-bold text-muted">
                                        <th className="min-w-200px">{intl.formatMessage({id: 'ORDERS.HEADER_PRODUCT'})}</th>
                                        <th>SKU</th>
                                        <th>{intl.formatMessage({id: 'ORDERS.HEADER_SELLER'})}</th>
                                        <th className="text-end">Qty</th>
                                        <th className="text-end">{intl.formatMessage({id: 'ORDERS.HEADER_TOTAL'})}</th>
                                        <th className="text-end min-w-150px">{intl.formatMessage({id: 'MODAL.CONTACT_SELLER'})}</th>
                                        <th className="text-end">{intl.formatMessage({id: 'ORDERS.LABEL_ACTION'})}</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {selectedOrder.items.map((item, idx) => {
                                        const sellerName = item.seller_name || item.vendor || 'Unknown';
                                        // Priority: 1. Manually saved per session, 2. Backend provided phone
                                        const phone = sellerPhones[sellerName] || (item.seller_phone && item.seller_phone !== 'N/A' ? item.seller_phone : '') || '';
                                        const isEditing = editingPhone[sellerName] || false;
                                        return (
                                            <tr key={idx}>
                                                <td className="fw-bold text-dark d-flex align-items-center">
                                                    {item.product_image && (
                                                        <div className='symbol symbol-35px me-3'>
                                                            <img src={item.product_image} alt={item.name} className="rounded" />
                                                        </div>
                                                    )}
                                                    <span>{item.name}</span>
                                                </td>
                                                <td className="text-muted">{item.sku}</td>
                                                <td className="text-danger fw-bold">{sellerName}</td>
                                                <td className="text-end">{item.qty_ordered}</td>
                                                <td className="text-end">{Number(item.price).toFixed(2)} {selectedOrder.order_currency_code}</td>
                                                <td className="text-end">
                                                    <div className="d-flex justify-content-end align-items-center gap-1">
                                                        {isEditing ? (
                                                            // ── Edit mode: input + Save + Cancel ──
                                                            <>
                                                                <div className="input-group input-group-sm" style={{ width: '160px' }}>
                                                                    <input
                                                                        type="text"
                                                                        className="form-control form-control-solid"
                                                                        placeholder="Ex: 21655000000"
                                                                        value={tempPhones[sellerName] ?? phone}
                                                                        autoFocus
                                                                        onChange={(e) => handlePhoneChange(sellerName, e.target.value)}
                                                                        onKeyDown={(e) => {
                                                                            if (e.key === 'Enter') savePhone(item);
                                                                            if (e.key === 'Escape') setEditingPhone(prev => ({ ...prev, [sellerName]: false }));
                                                                        }}
                                                                    />
                                                                    <button
                                                                        className="btn btn-sm btn-success"
                                                                        disabled={savingPhone[sellerName]}
                                                                        title="Save"
                                                                        onClick={async () => {
                                                                            await savePhone(item);
                                                                            setEditingPhone(prev => ({ ...prev, [sellerName]: false }));
                                                                        }}
                                                                    >
                                                                        {savingPhone[sellerName]
                                                                            ? <span className='spinner-border spinner-border-sm' />
                                                                            : <KTIcon iconName="check" className="fs-4" />}
                                                                    </button>
                                                                    <button
                                                                        className="btn btn-sm btn-light"
                                                                        title="Cancel"
                                                                        onClick={() => setEditingPhone(prev => ({ ...prev, [sellerName]: false }))}
                                                                    >
                                                                        <KTIcon iconName="cross" className="fs-4" />
                                                                    </button>
                                                                </div>
                                                            </>
                                                        ) : (
                                                            // ── Display mode: phone (or dash) + action buttons ──
                                                            <>
                                                                {phone ? (
                                                                    <>
                                                                        <span className="text-muted me-1 fs-7">{phone}</span>
                                                                        <button
                                                                            className="btn btn-icon btn-light-success btn-sm"
                                                                            title="Envoyer WhatsApp (vérification dispo)"
                                                                            disabled={sendingWhatsApp[item.item_id]}
                                                                            onClick={() => sendWhatsAppMessage(phone, item, selectedOrder!.entity_id)}
                                                                        >
                                                                            {sendingWhatsApp[item.item_id]
                                                                                ? <span className="spinner-border spinner-border-sm text-success" />
                                                                                : <KTIcon iconName="whatsapp" className="fs-2 text-success" />}
                                                                        </button>
                                                                    </>
                                                                ) : (
                                                                    <span className="text-muted fs-7 me-1">—</span>
                                                                )}
                                                                <button
                                                                    className="btn btn-icon btn-light-warning btn-sm"
                                                                    title="Edit phone"
                                                                    onClick={() => {
                                                                        setTempPhones(prev => ({ ...prev, [sellerName]: phone }));
                                                                        setEditingPhone(prev => ({ ...prev, [sellerName]: true }));
                                                                    }}
                                                                >
                                                                    <KTIcon iconName="pencil" className="fs-3 text-warning" />
                                                                </button>
                                                                <button
                                                                    className="btn btn-icon btn-light-info btn-sm"
                                                                    title="Add Comment"
                                                                    onClick={() => handleOpenCommentModal(item)}
                                                                >
                                                                    <KTIcon iconName="message-text-2" className="fs-2 text-info" />
                                                                </button>
                                                            </>
                                                        )}
                                                    </div>
                                                </td>
                                                <td className="text-end">
                                                    <button
                                                        className='btn btn-icon btn-light-info btn-sm'
                                                        onClick={() => navigate(`/products?sku=${item.sku}`)}
                                                        title='View Product'
                                                    >
                                                        <KTIcon iconName="package" className="fs-3" />
                                                    </button>
                                                </td>
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>

                        <div className="separator separator-dashed my-5"></div>
                        
                        <div className="row">
                            <div className="col-12">
                                <div className="form-check form-check-custom form-check-solid mb-3">
                                    <input 
                                        className="form-check-input" 
                                        type="checkbox" 
                                        checked={notifyCustomer} 
                                        onChange={(e) => setNotifyCustomer(e.target.checked)} 
                                        id="notifyCustomerCheck"
                                    />
                                    <label className="form-check-label fw-bold text-gray-700" htmlFor="notifyCustomerCheck">
                                        {intl.formatMessage({id: 'MODAL.NOTIFICATION_CHECK'})}
                                    </label>
                                </div>
                            </div>
                        </div>
                    </Modal.Body>
                    <Modal.Footer>
                        <Button variant="secondary" onClick={() => {
                            handleCloseModal();
                            setNotifyCustomer(false);
                        }}>{intl.formatMessage({id: 'MODAL.BUTTON_CLOSE'})}</Button>
                        
                        {isConfirmMode ? (
                            <Button variant="success" onClick={() => handleConfirmOrder()}>
                                Confirm Order
                            </Button>
                        ) : (
                            <>
                                <Button
                                    variant="primary"
                                    onClick={() => {
                                        updateStatus(selectedOrder.entity_id, 'confirmée');
                                        handleCloseModal();
                                    }}
                                >
                                    {intl.formatMessage({id: 'ORDERS.ACTION_CONFIRM'})}
                                </Button>
                                <Button
                                    variant="success"
                                    onClick={() => {
                                        updateStatus(selectedOrder.entity_id, 'Produits_dispo');
                                        handleCloseModal();
                                    }}
                                >
                                    {intl.formatMessage({id: 'ORDERS.ACTION_AVAILABLE'})}
                                </Button>
                                <Button
                                    variant="danger"
                                    onClick={() => {
                                        updateStatus(selectedOrder.entity_id, 'Produits_nondispo');
                                        handleCloseModal();
                                    }}
                                >
                                    {intl.formatMessage({id: 'ORDERS.ACTION_NOT_AVAILABLE'})}
                                </Button>
                            </>
                        )}
                    </Modal.Footer>
                </Modal>
            )}
            {showCommentModal && selectedItemForComment && (
                <Modal show={showCommentModal} onHide={handleCloseCommentModal} backdrop="static">
                    <Modal.Header closeButton>
                        <Modal.Title>Add Comment for {selectedItemForComment.name}</Modal.Title>
                    </Modal.Header>
                    <Modal.Body>
                        <Form.Group>
                            <Form.Label>Comment Content</Form.Label>
                            <Form.Control
                                as="textarea"
                                rows={3}
                                value={itemComment}
                                onChange={(e) => setItemComment(e.target.value)}
                                placeholder="Enter your comment here..."
                                autoFocus
                            />
                            <Form.Text className="text-muted">
                                We will automatically add "<strong>{selectedItemForComment.name}: </strong>" before your text.
                            </Form.Text>
                        </Form.Group>
                    </Modal.Body>
                    <Modal.Footer>
                        <Button variant="secondary" onClick={handleCloseCommentModal} disabled={commenting}>Cancel</Button>
                        <Button
                            variant="primary"
                            onClick={submitComment}
                            disabled={commenting || !itemComment.trim()}
                        >
                            {commenting ? (
                                <span className='indicator-progress' style={{ display: 'block' }}>
                                    Please wait...
                                    <span className='spinner-border spinner-border-sm align-middle ms-2'></span>
                                </span>
                            ) : 'Add Comment'}
                        </Button>
                    </Modal.Footer>
                </Modal>
            )}
            <Modal show={showExportModal} onHide={() => setShowExportModal(false)} centered>
                <Modal.Header closeButton>
                    <Modal.Title>Export Options</Modal.Title>
                </Modal.Header>
                <Modal.Body className="text-center py-10">
                    {isExporting ? (
                        <div className="py-10">
                            <div className="spinner-border text-primary mb-5" role="status">
                                <span className="visually-hidden">Loading...</span>
                            </div>
                            <p className="text-gray-600 fs-5 mb-0">Fetching all filtered results... Please wait.</p>
                        </div>
                    ) : (
                        <>
                            <p className="text-gray-600 mb-8 fs-5">Choose the format you want to export the data in:</p>
                            <div className="d-flex justify-content-center gap-4">
                                <button className="btn btn-outline btn-outline-dashed btn-outline-success btn-active-light-success px-10 py-5" onClick={handleExportCsv}>
                                    <i className="bi bi-filetype-csv fs-1 mb-2 d-block"></i>
                                    <span className="fw-bold fs-5">CSV</span>
                                </button>
                                <button className="btn btn-outline btn-outline-dashed btn-outline-primary btn-active-light-primary px-10 py-5" onClick={handleExportXls}>
                                    <i className="bi bi-filetype-xls fs-1 mb-2 d-block"></i>
                                    <span className="fw-bold fs-5">XLS</span>
                                </button>
                            </div>
                        </>
                    )}
                </Modal.Body>
            </Modal>
        </>
    )
}

export default MagentoOrdersAvailabilityPage
